// P-code semantics check for the DSP56000 module (both languages). Reads a case file (test/emu/
// cases.txt for DSP56000, cases156.txt for DSP56156, generated by cases.py / cases156.py), and for
// each case writes the code at p:0100, disassembles it (so REP and DO set their disassembly
// context), sets registers and memory, emulates with Ghidra's EmulatorHelper until the PC
// reaches the end of the main code, and compares registers and memory with values worked out
// by hand from the family manuals.
//
// Case file lines: case <name> / code <word hex> <word hex> ... / main <words> (optional)
//   set <reg> <value> | set <space>:<hexaddr> <value>      (one memory word)
//   expect <reg> <value> | expect <space>:<hexaddr> <value>
//   end
// Registers not set start at 0, except M0-M7 = FFFFh (linear addressing, the reset value).
// Script args: <cases.txt> <outfile>
//@category Testing

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.PrintStream;
import java.math.BigInteger;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import ghidra.app.emulator.EmulatorHelper;
import ghidra.app.script.GhidraScript;
import ghidra.program.model.address.Address;
import ghidra.program.model.address.AddressSet;
import ghidra.program.model.address.AddressSpace;
import ghidra.program.model.lang.Register;

public class DspEmuTest extends GhidraScript {

	private static class Case {
		String name;
		long[] code;
		int mainLen = -1;
		Map<String, BigInteger> set = new LinkedHashMap<>();
		Map<String, BigInteger> expect = new LinkedHashMap<>();
	}

	private static BigInteger num(String s) {
		boolean neg = s.startsWith("-");
		if (neg) {
			s = s.substring(1);
		}
		BigInteger v = s.startsWith("0x") ? new BigInteger(s.substring(2), 16) : new BigInteger(s);
		return neg ? v.negate() : v;
	}

	private List<Case> load(String path) throws Exception {
		List<Case> cases = new ArrayList<>();
		Case c = null;
		try (BufferedReader r = new BufferedReader(new FileReader(path))) {
			String line;
			while ((line = r.readLine()) != null) {
				line = line.trim();
				if (line.isEmpty() || line.startsWith("#")) {
					continue;
				}
				String[] f = line.split("\\s+");
				switch (f[0]) {
					case "case":
						c = new Case();
						c.name = f[1];
						break;
					case "code":
						c.code = new long[f.length - 1];
						for (int i = 1; i < f.length; i++) {
							c.code[i - 1] = Long.parseLong(f[i], 16);
						}
						break;
					case "main":
						c.mainLen = Integer.decode(f[1]);
						break;
					case "set":
						c.set.put(f[1], num(f[2]));
						break;
					case "expect":
						c.expect.put(f[1], num(f[2]));
						break;
					case "end":
						cases.add(c);
						break;
					default:
						throw new IllegalArgumentException("bad line: " + line);
				}
			}
		}
		return cases;
	}

	private int unit(AddressSpace sp) {
		return sp.getAddressableUnitSize();
	}

	private Address waddr(String space, long word) {
		AddressSpace sp = currentProgram.getAddressFactory().getAddressSpace(space);
		return sp.getAddress(word * unit(sp));
	}

	private Address loc(String l) {
		String[] p = l.split(":");
		return waddr(p[0], Long.parseLong(p[1], 16));
	}

	private byte[] wordBytes(long v, int n) {
		byte[] b = new byte[n];
		for (int i = 0; i < n; i++) {
			b[n - 1 - i] = (byte) (v >> (8 * i));
		}
		return b;
	}

	private String runCase(Case c) throws Exception {
		AddressSpace psp = currentProgram.getAddressFactory().getAddressSpace("p");
		int pu = unit(psp);
		Address start = waddr("p", 0x100);
		int mainLen = c.mainLen >= 0 ? c.mainLen : c.code.length;
		Address end = waddr("p", 0x100 + mainLen);
		AddressSet body = new AddressSet(start, waddr("p", 0x100 + c.code.length + 8));
		clearListing(body);
		currentProgram.getProgramContext().remove(start, waddr("p", 0x100 + c.code.length + 8),
			currentProgram.getLanguage().getContextBaseRegister());
		for (int i = 0; i < c.code.length; i++) {
			setBytes(waddr("p", 0x100 + i), wordBytes(c.code[i], pu));
		}
		// a zero (NOP) word after the code so linear disassembly stops cleanly
		disassemble(start);

		EmulatorHelper emu = new EmulatorHelper(currentProgram);
		try {
			for (int i = 0; i < 8; i++) {
				Register m = currentProgram.getRegister("M" + i);
				if (m != null) {
					emu.writeRegister(m, BigInteger.valueOf(0xffff));
				}
			}
			for (Map.Entry<String, BigInteger> e : c.set.entrySet()) {
				if (e.getKey().contains(":")) {
					Address a = loc(e.getKey());
					emu.writeMemory(a, wordBytes(e.getValue().longValue(),
						unit(a.getAddressSpace())));
				}
				else {
					Register r = currentProgram.getRegister(e.getKey());
					BigInteger v = e.getValue();
					if (v.signum() < 0) {
						v = v.add(BigInteger.ONE.shiftLeft(8 * r.getMinimumByteSize()));
					}
					emu.writeRegister(r, v);
				}
			}
			emu.writeRegister(emu.getPCRegister(), BigInteger.valueOf(0x100));
			int steps = 0;
			while (!emu.getExecutionAddress().equals(end)) {
				if (++steps > 2000) {
					return "did not reach the end (pc " + emu.getExecutionAddress() + ")";
				}
				if (!emu.step(monitor)) {
					return "emulation error at " + emu.getExecutionAddress() + ": " +
						emu.getLastError();
				}
			}
			StringBuilder bad = new StringBuilder();
			for (Map.Entry<String, BigInteger> e : c.expect.entrySet()) {
				BigInteger got;
				BigInteger want = e.getValue();
				if (e.getKey().contains(":")) {
					Address a = loc(e.getKey());
					int n = unit(a.getAddressSpace());
					got = new BigInteger(1, emu.readMemory(a, n));
					if (want.signum() < 0) {
						want = want.add(BigInteger.ONE.shiftLeft(8 * n));
					}
				}
				else {
					Register r = currentProgram.getRegister(e.getKey());
					got = emu.readRegister(r);
					if (want.signum() < 0) {
						want = want.add(BigInteger.ONE.shiftLeft(8 * r.getMinimumByteSize()));
					}
				}
				if (!got.equals(want)) {
					bad.append(String.format(" %s=0x%x (expected 0x%x)", e.getKey(), got, want));
				}
			}
			return bad.length() == 0 ? null : bad.toString().trim();
		}
		finally {
			emu.dispose();
		}
	}

	@Override
	protected void run() throws Exception {
		String[] args = getScriptArgs();
		List<Case> cases = load(args[0]);
		PrintStream out = new PrintStream(args[1]);
		int pass = 0, fail = 0;
		for (Case c : cases) {
			String err;
			try {
				err = runCase(c);
			}
			catch (Exception ex) {
				err = "exception: " + ex;
			}
			if (err == null) {
				pass++;
				out.println("PASS " + c.name);
			}
			else {
				fail++;
				out.println("FAIL " + c.name + ": " + err);
			}
		}
		out.printf("emulation (%s): %d passed, %d failed%n", currentProgram.getLanguageID(), pass,
			fail);
		out.close();
	}
}
